const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: '-2' },
      { kind: 'text', payload: '-3' },
      { kind: 'text', payload: 'P(-2,-3)' },
      { kind: 'text', payload: '第三象限' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var u = Math.min(W / 12, H / 10);
    var originX = W * 0.58;
    var originY = H * 0.44;
    var pointX = originX - 2 * u;
    var pointY = originY + 3 * u;
    var xLeft = 34;
    var xRight = W - 34;
    var yTop = 34;
    var yBottom = H - 34;
    var colorAxis = '#223344';
    var colorDash = '#c2410c';
    var colorPoint = '#b91c1c';
    var colorText = '#1f2937';
    var colorQuad = '#1d4ed8';

    var xNeg = visualSdk.polyline([[xLeft, originY], [originX, originY]]);
    var xPosArrow = visualSdk.arrow(originX, originY, xRight, originY, {});
    var yNeg = visualSdk.polyline([[originX, yBottom], [originX, originY]]);
    var yPosArrow = visualSdk.arrow(originX, originY, originX, yTop, {});
    var dashV = visualSdk.polyline([[pointX, pointY], [pointX, originY]]);
    var dashH = visualSdk.polyline([[pointX, pointY], [originX, pointY]]);
    var point = visualSdk.circle(pointX, pointY, 5);

    return {
      schemaVersion: 1,
      sceneId: 'source-transcription-point-p',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xNeg', commands: xNeg },
        { id: 'xPosArrow', commands: xPosArrow },
        { id: 'yNeg', commands: yNeg },
        { id: 'yPosArrow', commands: yPosArrow },
        { id: 'dashV', commands: dashV },
        { id: 'dashH', commands: dashH },
        { id: 'point', commands: point }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'xNeg', fill: colorAxis, stroke: { width: 2 } },
        { type: 'path', pathId: 'xPosArrow', fill: colorAxis, stroke: { width: 2 } },
        { type: 'path', pathId: 'yNeg', fill: colorAxis, stroke: { width: 2 } },
        { type: 'path', pathId: 'yPosArrow', fill: colorAxis, stroke: { width: 2 } },
        { type: 'path', pathId: 'dashV', fill: colorDash, stroke: { width: 1.6, dash: [6, 4] } },
        { type: 'path', pathId: 'dashH', fill: colorDash, stroke: { width: 1.6, dash: [6, 4] } },
        { type: 'path', pathId: 'point', fill: colorPoint, stroke: { width: 1.5 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: xRight - 8, y: originY - 12 }, hAlign: 'center', vAlign: 'bottom', color: colorText },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: originX + 12, y: yTop + 2 }, hAlign: 'left', vAlign: 'middle', color: colorText },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: originX - 8, y: originY + 8 }, hAlign: 'right', vAlign: 'top', color: colorText },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: pointX, y: originY + 8 }, hAlign: 'center', vAlign: 'top', color: colorText },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: originX - 8, y: pointY - 8 }, hAlign: 'right', vAlign: 'bottom', color: colorText },
        { type: 'label', contentId: metrics[5].contentId, anchor: { x: pointX + 9, y: pointY + 10 }, hAlign: 'left', vAlign: 'top', color: colorPoint },
        { type: 'label', contentId: metrics[6].contentId, anchor: { x: Math.max(24, originX - 4.8 * u), y: Math.min(H - 24, originY + 4.2 * u) }, hAlign: 'left', vAlign: 'bottom', color: colorQuad }
      ] }
    };
  }
};
